}
export function canonicalSchufa(value:any){
 const raw=clean(value);if(!raw)return'NOT_SPECIFIED';
 if(raw==='AVAILABLE')return'PRESENT_RECENT';
 if(['PRESENT_RECENT','NOT_AVAILABLE','NOT_SPECIFIED'].includes(raw))return raw;
