  if(!/^\d{5}$/.test(clean(profile?.postcode)))missing.push('PLZ');
  add('Ort',profile?.city);
  selected('SCHUFA-Status',canonicalSchufa(profile?.schufa_status));
  selected('Haushaltstyp',canonicalHousehold(profile?.household_type));
