async function detail(x:{url:string,lastmod:string}){const r=await get(x.url),p=strip(r.text),h1=r.text.match(/<h1\b[^>]*>[\s\S]*?<\/h1>/i)?.[0]||'',title=clean(strip(h1))||'Covivio Wohnungsangebot';if(/\b(?:Laden|Ladenfläche|Lager|Lagerfläche|Gewerbe|Büro|Praxis|Stellplatz|Parkplatz|Garage)\b/i.test(title))return null;if(!/Anzahl\s+Zimmer/i.test(p))return null;const at=h1?r.text.indexOf(h1)+h1.length:0,after=strip(r.text.slice(at,at+1800)),a=after.match(/([A-ZÄÖÜ][A-Za-zÄÖÜäöüß.'’-]*(?:\s+[A-Za-zÄÖÜäöüß.'’-]+){0,4}\s+\d+[a-zA-Z]?)\s*,\s*(2\d{4})\s+Hamburg/i)||p.match(/([A-ZÄÖÜ][A-Za-zÄÖÜäöüß.'’-]*(?:\s+[A-Za-zÄÖÜäöüß.'’-]+){0,4}\s+\d+[a-zA-Z]?)\s*,\s*(2\d{4})\s+Hamburg/i),street=clean(a?.[1]),zip=a?.[2]||null;if(!zip||!HH_ZIPS.has(zip))return null;const warm=money(p.match(/Gesamtmiete\s*\|?\s*([\d.]+,\d{2})\s*€/i)?.[1]||p.match(/([\d.]+,\d{2})\s*€\s+Gesamtmiete/i)?.[1]),cold=money(p.match(/Mietpreis\s*\|?\s*([\d.]+,\d{2})\s*€/i)?.[1]||p.match(/Kaltmiete\s*\|?\s*([\d.]+,\d{2})\s*€/i)?.[1]);if(warm==null&&cold==null)return null;const objectId=clean(p.match(/Objekt.?nummer\s*\|?\s*([A-Z0-9.-]+)/i)?.[1]),slug=new URL(r.url).pathname.split('/').filter(Boolean).at(-1)||r.url;return{id:objectId||slug,url:r.url,title,streetAddress:street,postalCode:zip,addressLocality:'Hamburg',warmRent:warm,coldRent:cold,operatingCosts:money(p.match(/Betriebskosten\s*\|?\s*([\d.]+,\d{2})\s*€/i)?.[1]),heatingCosts:money(p.match(/Heizkosten\s*\|?\s*([\d.]+,\d{2})\s*€/i)?.[1]),deposit:money(p.match(/Kaution\s*\|?\s*([\d.]+,\d{2})\s*€/i)?.[1]),rooms:num(p.match(/Anzahl\s+Zimmer\s*\|?\s*([\d.,]+)/i)?.[1]),area:num(p.match(/Fläche\s*\|?\s*([\d.,]+)\s*m/i)?.[1]),provider:'covivio',lastmod:x.lastmod,discovery_lane:'official_sitemap',imageUrl:image(r.text,r.url)}}

